create table "devcontrol"."devworkrequests" (
  "id"           bigint                   generated by default as identity not null,
  "workflow_key" text                     not null,
  "payload"      jsonb                    not null default '{}'::jsonb,
  "status"       text                     not null default 'pending'::text,
  "created_at"   timestamp with time zone not null default now(),
  "updated_at"   timestamp with time zone not null default now(),
  constraint "devworkrequests_pkey" primary key (id)
);

grant delete, insert, maintain, references, select, trigger, truncate, update on table "devcontrol"."devworkrequests" to "postgres";
